'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',curriculum:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4zM13 7a3 3 0 0 1 3-3h5v15h-4a4 4 0 0 0-4 2"/>',lab:'<path d="M8 3h8M10 3v7L4 20h16l-6-10V3M7 15h10"/>',resources:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M8 4v17M12 8h5M12 12h5"/>',checks:'<path d="m4 6 2 2 4-4M13 6h7M4 13l2 2 4-4M13 13h7M4 20h16"/>',progress:'<path d="M4 20h17M7 16v-5M12 16V7M17 16V3"/>'};
const svg=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]}</svg>`;
const dataArt=`<svg viewBox="0 0 80 80" aria-hidden="true"><ellipse cx="25" cy="20" rx="14" ry="6"/><path d="M11 20v28c0 8 28 8 28 0V20M11 34c0 8 28 8 28 0M39 36h18v17M51 47l6 6 6-6"/><rect x="45" y="55" width="25" height="14" rx="3"/><path d="M51 60h13M51 64h8"/></svg>`;
icons.videos='<path d="m9 7 8 5-8 5z"/><rect x="2" y="3" width="20" height="18" rx="3"/>';
const routes={overview:'Overview',curriculum:'Curriculum',lab:'Pipeline lab',resources:'Resource library',videos:'Watch & learn',checks:'Knowledge checks',progress:'My progress'};
let resources=[],documents={},modules=[],state,session=false,page='overview',resourceFilter='All',resourceSearch='',videoFilter='All',readerMode='text',readerScale=1,quizRun=null;
const fresh=()=>({completed:[],quizzes:{},notes:{},saved:[],lab:false});
try{state={...fresh(),...JSON.parse(localStorage.getItem('data-studio-progress')||'{}')};if(!Array.isArray(state.completed)||!Array.isArray(state.saved)||typeof state.quizzes!=='object'||!state.quizzes||!state.notes||typeof state.notes!=='object')state=fresh()}catch{state=fresh()}
try{session=sessionStorage.getItem('data-studio-demo')==='yes'}catch{}
const save=()=>{try{localStorage.setItem('data-studio-progress',JSON.stringify(state))}catch{toast('Browser storage is unavailable. Progress lasts for this visit.')}};
const completed=()=>state.completed.filter(id=>allLessons().some(l=>l.id===id)).length;const passed=()=>modules.filter(m=>state.quizzes[m.id]?.best>=80).length;const allLessons=()=>modules.flatMap(m=>m.lessons.map(l=>({...l,module:m})));
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function updateProfile(){$('#profile-name').textContent=session?'Aarav · Demo learner':'Guest learner';$('#avatar').textContent=session?'A':'G'}
function nav(){ const active=page==='reader'?'resources':page;$('#navigation').innerHTML=Object.entries(routes).map(([key,label])=>`<a href="#${key}" class="${active===key?'active':''}" ${active===key?'aria-current="page"':''}>${svg(key)}<span>${label}</span></a>`).join('');$('#page-name').textContent=page==='reader'?'Resource reader':routes[page] }
function intro(eyebrow,title,description){return `<div class="section-intro"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div>`}
function stats(){return `<div class="stats"><div class="stat"><strong>${completed()}<small> / ${allLessons().length}</small></strong><p>Lessons completed</p></div><div class="stat"><strong>${passed()}<small> / 5</small></strong><p>Knowledge checks passed</p></div><div class="stat"><strong>${state.saved.length}</strong><p>Resources saved</p></div><div class="stat daily"><span class="circle">✧</span><div><b>A little practice goes a long way.</b><button data-quiz="1">Try a quick knowledge check ↗</button></div></div></div>`}
function moduleRows(list=modules){return list.map(m=>`<details class="module-row ${m.color}" data-module="${m.id}"><summary class="module-top"><span class="module-number">0${m.id}</span><span class="module-title"><h3>${m.name}</h3><p>${m.outcome} · ${m.lessons.length} lessons · ${m.lessons.filter(l=>state.completed.includes(l.id)).length}/${m.lessons.length} complete</p></span><small>MODULE 0${m.id}</small><span class="expand">+</span></summary><div class="lesson-list"><p class="source-note">${m.description}</p>${m.lessons.map(l=>`<button class="lesson-row ${state.completed.includes(l.id)?'completed':''}" data-lesson="${l.id}"><span class="lesson-check">${state.completed.includes(l.id)?'✓':'○'}</span><span>${l.title}</span><span class="lesson-end">↗</span></button>`).join('')}<button class="lesson-row" data-quiz="${m.id}"><span class="lesson-check">?</span><span>Module ${m.id} knowledge check</span><span class="lesson-end">${state.quizzes[m.id]?.best>=80?'✓ Passed':'10 questions →'}</span></button></div></details>`).join('')}
function overview(){let next=allLessons().find(l=>!state.completed.includes(l.id))||allLessons()[0];return `<div class="welcome"><div><h1>${session?'Welcome back, Aarav.':'Good things start with curiosity.'}</h1><p>Your journey from raw data to real-world machine learning.</p></div><span class="pill">A workspace for engineering minds</span></div><section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><span class="eyebrow">DATA ENGINEERING & MLOPS · YOUR NEXT CHAPTER</span><h2 id="hero-title">Good data.<br><em>Great possibilities.</em></h2><p>Build reliable pipelines. Bring models to life.<br>Learn the craft behind intelligent systems.</p><div class="hero-actions"><button class="button orange" data-lesson="${next.id}">${completed()?'Continue learning':'Start your first lesson'} <span>↗</span></button><a class="button text" href="#curriculum">Explore the course →</a></div></div><div class="hero-art"><img src="assets/students.png" alt="Engineering students collaborating on a data pipeline project in a sunlit campus studio" fetchpriority="high"><div class="photo-caption"><span>✧</span> Your next big idea starts here.</div></div></section>${stats()}<div class="content-grid"><div><div class="section-heading"><h2>${completed()?'Keep the momentum':'Your starting point'}</h2><a href="#progress">View my progress ↗</a></div><article class="continue-card"><div class="module-art">${dataArt}</div><div class="continue-content"><div class="tiny">MODULE 0${next.module.id} · ${next.module.outcome}</div><h3>${next.title}</h3><p>${next.module.name} <span>·</span> A focused lesson + a small activity</p><button class="button light" data-lesson="${next.id}">${completed()?'Continue lesson':'Let’s begin'} →</button></div></article><div class="section-heading"><div><h2>One course. A complete journey.</h2><p>Five modules. Twenty lessons. Fifty ways to test your understanding.</p></div><a href="#curriculum">View all ↗</a></div><div class="module-list">${moduleRows()}</div></div><aside class="right-column"><article class="feature-note"><span class="eyebrow">LEARN IT. CONNECT IT. BUILD IT.</span><h3>Think in pipelines,<br>not just predictions.</h3><div class="pipeline-mini"><b>Data</b><span>→</span><b>Model</b><span>→</span><b>Deploy</b></div><p>Connect the dots between a dataset and a dependable machine learning system.</p><button data-route="lab">Step into the pipeline lab ↗</button></article><a class="download-note" href="#reader/study"><span class="pdf-icon">PDF</span><div><b>A companion for your journey</b><p>Five modules. One study guide.</p></div><span class="arrow">↗</span></a></aside></div><section class="overview-videos"><div class="section-heading"><div><h2>Watch an idea come to life.</h2><p>Learn from practitioners, then bring the idea back to your project.</p></div><a href="#videos">All 8 videos ↗</a></div><div class="video-grid">${resources.filter(r=>r.video).slice(0,3).map(videoCard).join('')}</div></section>`}
function curriculum(){return `${intro('YOUR FLEXIBLE COURSE MAP','From raw data to responsible AI.','Learn at your own pace across five connected modules. Read the concepts, work through examples, watch a practitioner explain them, then test your understanding.')}<div class="tools-bar"><label class="sr-only" for="lesson-search">Search lessons</label><input class="search" id="lesson-search" placeholder="Search a topic — architecture, drift, deployment…" type="search"></div><div class="module-list" id="curriculum-list">${moduleRows()}</div><div class="empty" id="search-empty" hidden>No matching topics. Try “data”, “model” or “production”.</div><div class="callout"><b>A practical, self-paced journey</b><br>5 modules · 20 lessons · 50 quiz questions · 8 videos · 2 guided projects.<br>Start with basic programming and SQL familiarity. Move in sequence or revisit a topic when your project needs it.</div><button class="button light" data-resource="guide">Read the course guide →</button>`}
function resourceCards(){return resources.filter(r=>(resourceFilter==='All'||(resourceFilter==='Saved'?state.saved.includes(r.id):r.type===resourceFilter))&&(`${r.title} ${r.desc} ${r.creator||''}`.toLowerCase().includes(resourceSearch))).map(r=>`<article class="resource-card"><span class="resource-type">${r.format} / ${r.type.toUpperCase()}</span><h3>${r.title}</h3><p>${r.desc}</p><div class="card-bottom"><button class="button light" data-resource="${r.id}">${r.video?'Watch here':r.document?'Read here':'Read study brief'} →</button><button class="save-button" data-save="${r.id}" aria-pressed="${state.saved.includes(r.id)}">${state.saved.includes(r.id)?'✓ Saved':'+ Save'}</button></div></article>`).join('')||'<div class="empty full">No resources match your selection. Try another filter or search term.</div>'}
function library(){return `${intro('THE NXGENVARSITY LEARNING LIBRARY','Read, watch, connect.','Open every guide, study brief and video inside your learning workspace. Keep useful resources on your saved shelf.')}<div class="tools-bar"><label for="resource-search" class="sr-only">Search resources</label><input class="search" id="resource-search" type="search" placeholder="Find a guide, video or study brief…" value="${esc(resourceSearch)}">${['All','Course guide','Study notes','Projects','Practice','Video','Reading','Saved'].map(t=>`<button class="filter ${resourceFilter===t?'active':''}" data-filter="${t}">${t}</button>`).join('')}</div><div class="resource-grid" id="resource-grid">${resourceCards()}</div><div class="book-list"><h2>Take the next chapter further.</h2><p><b>Core reading</b><br>Joe Reis & Matt Housley · <i>Fundamentals of Data Engineering</i> (2022)<br>Mark Treveil & the Dataiku Team · <i>Introducing MLOps</i> (2020)</p><p><b>Further reading</b><br>Martin Kleppmann · <i>Designing Data-Intensive Applications</i><br>Andriy Burkov · <i>Machine Learning Engineering</i><br>Noah Gift & Alfredo Deza · <i>Practical MLOps</i></p><p class="source-note">Study briefs are original explanations with links to further reading. Videos belong to their credited creators; platform interfaces in older recordings may differ from current versions.</p></div>`}
let pipeline=['Deploy & monitor','Validate data','Train model','Ingest data','Evaluate model','Engineer features'];const pipelineCorrect=['Ingest data','Validate data','Engineer features','Train model','Evaluate model','Deploy & monitor'];
function pipelineMarkup(){return pipeline.map((s,i)=>`<div class="pipeline-step"><span>0${i+1}</span><strong>${s}</strong><button class="move-button" data-move="${i}" data-direction="-1" aria-label="Move ${s} up" ${i===0?'disabled':''}>↑</button><button class="move-button" data-move="${i}" data-direction="1" aria-label="Move ${s} down" ${i===pipeline.length-1?'disabled':''}>↓</button></div>`).join('')}
function lab(){return `${intro('THE PIPELINE LAB · PRACTICE WITH PURPOSE','Make the connections yourself.','A small design exercise to connect the course concepts. This browser simulation does not train or deploy a real model.')}<div class="lab-layout"><section class="lab-board"><span class="resource-type">EXERCISE 01 / ORDER THE PIPELINE</span><h2>From dataset to deployment</h2><p>You’re designing a first-pass house-price prediction workflow. Use the arrows to put these stages in a sensible order. Real systems may iterate through these stages.</p><div class="pipeline-steps" id="pipeline-steps">${pipelineMarkup()}</div><div class="lab-actions"><button class="button" id="check-pipeline">Check my pipeline →</button><button class="button light" id="reset-pipeline">Reset exercise</button></div><div id="lab-feedback" class="feedback" role="status"></div></section><aside><article class="assignment"><span class="resource-type">GUIDED PROJECT 01</span><h3>Design your own MLOps pipeline.</h3><p>Choose house-price prediction, customer churn or fraud detection. Document:</p><ul><li>The business objective and data sources</li><li>EDA, features and an evaluation plan</li><li>Versioning and reproducibility</li><li>A complete pipeline diagram</li></ul></article><article class="assignment"><span class="resource-type">GUIDED PROJECT 02</span><h3>Explore an MLOps tool.</h3><p>Study MLflow, Kubeflow or TFX. Explain CI/CD support, model validation, a deployment strategy, and practical advantages and challenges.</p><a class="inline-link" href="#reader/workbook">Get the project workbook ↗</a></article></aside></div>`}
function checks(){return `${intro('PAUSE. REFLECT. CONNECT.','Fifty questions. Deeper understanding.','Each module has ten questions with explanations. Answer once per question, review the reasoning, and aim for 80% to pass. Your best result stays in this browser.')}<div class="mixed-check"><div><span class="resource-type">MIXED PRACTICE / 10 QUESTIONS</span><h2>Connect ideas across the course.</h2><p>A fresh selection from all five modules, with shuffled answer choices.</p></div><button class="button orange" data-quiz="mixed">Start mixed practice →</button></div><div class="quiz-grid">${modules.map(m=>{const score=state.quizzes[m.id];return `<article class="quiz-card"><span class="resource-type">MODULE 0${m.id} / 10 QUESTIONS</span><h3>${m.name}</h3><p>${m.description}</p>${score&&typeof score==='object'?`<span class="${score.best>=80?'quiz-done':'quiz-progress'}">${score.best>=80?'✓ Passed · ':''}Best: ${score.best}% · ${score.attempts} attempt${score.attempts===1?'':'s'}</span>`:''}<button class="button light" data-quiz="${m.id}">${score&&typeof score==='object'?'Practice again':'Take the check'} →</button></article>`}).join('')}</div><div class="callout">Prefer paper? <button class="inline-link" data-resource="quizbook">Read the 50-question revision workbook →</button></div>`}
function progress(){return `${intro('YOUR LEARNING, ONE STEP AT A TIME','Every connection counts.','Lessons, assessments, notes and saved resources stay in this browser. Guest and demo modes share the same record. They do not sync between devices.')}${stats()}<div class="progress-layout"><section class="progress-panel"><h2>Your module progress</h2>${modules.map(m=>{let n=m.lessons.filter(l=>state.completed.includes(l.id)).length;return `<div class="progress-item"><div><span>0${m.id} · ${m.name}</span><span>${n}/${m.lessons.length}</span></div><div class="progress-track" role="progressbar" aria-label="${m.name}" aria-valuemin="0" aria-valuemax="${m.lessons.length}" aria-valuenow="${n}"><div class="progress-fill" style="width:${n/m.lessons.length*100}%"></div></div></div>`}).join('')}<a class="button light" href="#curriculum">Keep learning →</a></section><section class="progress-panel"><h2>Your assessment record</h2><p class="quiz-progress">${passed()} of 5 module assessments passed · pass mark 80%</p>${modules.map(m=>{let q=state.quizzes[m.id];return `<button class="lesson-row" data-quiz="${m.id}"><span class="lesson-check">${q?.best>=80?'✓':'○'}</span><span>Module 0${m.id} · ${m.outcome}</span><span class="lesson-end">${q&&typeof q==='object'?q.best+'%':'Try it →'}</span></button>`}).join('')}<div class="callout" style="margin-bottom:0">Pipeline design exercise: <b>${state.lab?'Completed ✓':'Ready when you are'}</b></div></section><section class="progress-panel full"><div class="section-heading"><h2>Your notebook</h2><button id="export-notes">Export notes ↓</button></div>${allLessons().filter(l=>state.notes[l.id]?.trim()).map(l=>`<article class="note-entry"><b>${l.title}</b><p>${esc(state.notes[l.id])}</p><button class="button light" data-lesson="${l.id}">Revisit lesson ↗</button></article>`).join('')||'<p class="quiz-progress">Add a note inside any lesson to start your notebook.</p>'}</section></div>`}
function render(){const route=location.hash.slice(1).split('/');page=route[0];if(page!=='reader'&&!routes[page])page='overview';nav();$('#main').innerHTML=page==='reader'?reader(route[1],Number(route[2])||0):({overview,curriculum,lab,resources:library,videos,checks,progress}[page])();updateProfile()}
function openModal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0}
function lesson(id){let l=allLessons().find(l=>l.id===id);if(!l)return;let done=state.completed.includes(id),next=allLessons()[allLessons().findIndex(x=>x.id===id)+1];openModal(`<div class="modal-eyebrow">MODULE 0${l.module.id} · ${l.module.outcome} / LESSON ${id.slice(-1)}</div><h2 class="modal-title" id="modal-title">${l.title}</h2><p class="modal-objective">${l.objective}</p>${l.sections.map(s=>`<section class="lesson-section"><h3>${s.title}</h3><p>${s.body}</p></section>`).join('')}${l.code?`<figure class="code-example"><figcaption>WORKED EXAMPLE</figcaption><pre><code>${esc(l.code)}</code></pre><p>${esc(l.codeCaption)}</p></figure>`:''}<div class="activity"><b>PUT THE IDEA TO WORK</b>${l.activity}</div><div class="lesson-resources"><b>Watch the idea in practice</b>${l.module.videoIds.map(id=>{let v=resources.find(r=>r.id===id);return `<button data-resource="${v.id}">${v.title} <span>↗</span></button>`}).join('')}</div><label class="notes-label" for="lesson-note">Your reflection or working notes</label><textarea class="notes-field" id="lesson-note" placeholder="Capture an idea, try the activity, or write a question…">${esc(state.notes[id]||'')}</textarea><button class="button light" data-note="${id}">Save note</button><div class="modal-actions"><button class="button" data-complete="${id}">${done?'✓ Completed · mark incomplete':'Mark lesson complete ✓'}</button>${next?`<button class="button light" data-lesson="${next.id}">Next lesson →</button>`:`<button class="button light" data-quiz="5">Try the module check →</button>`}</div><p class="source-note">Further reading: ${l.module.chapters}.</p>`);$('#lesson-note').dataset.lesson=id}
function login(){if(session){openModal(`<div class="login"><span class="brandmark">d</span><div class="modal-eyebrow">DEMO LEARNER ACCOUNT</div><h2 class="modal-title" id="modal-title">Welcome, Aarav.</h2><p>You’re exploring the studio with a demo account. Progress and notes are stored in this browser.</p><a class="button light" href="#progress" id="profile-progress">View my progress →</a><button class="button" id="logout">Sign out of demo</button></div>`);return}openModal(`<div class="login"><span class="brandmark">d</span><div class="modal-eyebrow">YOUR LEARNING SPACE</div><h2 class="modal-title" id="modal-title">Hello, curious mind.</h2><p>Try the student experience with the demo account.</p><form id="login-form"><label for="email">Email address</label><input id="email" type="email" autocomplete="off" placeholder="student@datastudio.demo" required><label for="password">Demo password</label><input id="password" type="password" autocomplete="off" placeholder="Enter the demo password" required><div id="login-error" role="alert" class="feedback error"></div><button class="button" type="submit">Enter the studio →</button></form><button class="button light" id="use-demo">Use demo account</button><div class="demo-details">Email: <code>student@datastudio.demo</code><br>Password: <code>LearnData123!</code></div><small>Demo only. Use the credentials shown above; do not enter a real password. No account is created.</small></div>`)}
function signIn(){session=true;try{sessionStorage.setItem('data-studio-demo','yes')}catch{}$('#modal').close();render();toast('Welcome, Aarav. Your learning space is ready.')}
function quiz(id){let m=modules.find(m=>String(m.id)===String(id));const qs=id==='mixed'?shuffle(modules.flatMap(m=>m.quizzes)).slice(0,10):m?.quizzes;if(!qs)return;quizRun={key:String(id),title:m?m.name:'Mixed course practice',qs:qs.map(q=>({...q,choices:shuffle(q.options.map((text,i)=>({text,correct:i===q.answer})))})),index:0,responses:[],selected:null,checked:false,finished:false};drawQuestion()}

const shuffle=items=>{const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function videoCard(v){return `<article class="video-card"><button class="video-thumb" data-resource="${v.id}" aria-label="Watch ${esc(v.title)}"><img src="https://i.ytimg.com/vi/${v.video}/hqdefault.jpg" alt="" loading="lazy"><span class="play-circle">▶</span><span class="video-module">MODULE 0${v.module}</span></button><div><span class="resource-type">${v.creator}</span><h3><button data-resource="${v.id}">${v.title}</button></h3><p>${v.desc}</p></div></article>`}
function videos(){return `${intro('WATCH & LEARN / 8 CURATED VIDEOS','See the systems behind the ideas.','Explore explanations from IBM, Google Cloud and Databricks. Each video has a reflection prompt to connect it with your own project.')}<div class="tools-bar">${['All',...modules.map(m=>String(m.id))].map(id=>`<button class="filter ${videoFilter===id?'active':''}" data-video-filter="${id}">${id==='All'?'All videos':'Module 0'+id}</button>`).join('')}</div><div class="video-grid" id="video-grid">${videoCards()}</div><p class="source-note">Videos are embedded from their creators’ YouTube channels. Historical sessions teach concepts, while product screens and setup steps may have changed. If a creator restricts embedding, use the YouTube link in the reader.</p>`}
function videoCards(){return resources.filter(r=>r.video&&(videoFilter==='All'||String(r.module)===videoFilter)).map(videoCard).join('')}
function resourceRoute(id,index=0){readerMode='text';location.hash=`reader/${id}/${index}`}
function readerBlock(b){switch(b.type){case 'image':return `<img class="reader-image" src="${b.src}" alt="${esc(b.alt||'Course visual')}">`;case 'heading':return `<h3>${esc(b.text)}</h3>`;case 'code':return `<pre><code>${esc(b.text)}</code></pre>`;case 'list':return `<ul>${b.items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`;case 'lines':return '<div class="writing-lines" aria-label="Space for your written reflection"></div>';case 'callout':return `<div class="activity">${esc(b.text)}</div>`;case 'link':return `<p><a class="inline-link" href="${b.url}" target="_blank" rel="noopener">${esc(b.text)} ↗</a></p>`;default:return `<p>${esc(b.text)}</p>`}}
function reader(id,index){const r=resources.find(r=>r.id===id);if(!r)return `${intro('RESOURCE READER','That resource could not be found.','Choose a guide, video or study brief from the library.')}<a class="button" href="#resources">Back to the library</a>`;if(r.video)return `<a class="reader-back" href="#videos">← Back to videos</a>${intro(r.creator.toUpperCase()+' / MODULE 0'+r.module,r.title,r.desc)}<div class="video-layout"><section><div class="video-player" id="video-player"><img src="https://i.ytimg.com/vi/${r.video}/hqdefault.jpg" alt=""><button class="button orange" data-play="${r.id}">▶ Play video here</button></div><div class="video-meta"><span>Video by ${r.creator}</span><a href="${r.url}" target="_blank" rel="noopener">Watch on YouTube ↗</a></div><p class="source-note">If playback is unavailable here, the creator’s YouTube page is available above. This recording may show an earlier version of the platform.</p></section><aside class="assignment"><span class="resource-type">WATCH WITH A QUESTION</span><h3>Bring the idea back to your project.</h3><p>${r.prompt}</p><button class="button light" data-lesson="m${r.module}l4">Open a worked example →</button><button class="save-button" data-save="${r.id}">${state.saved.includes(r.id)?'✓ Saved':'+ Save video'}</button></aside></div>`;
 if(r.sections)return `<a class="reader-back" href="#resources">← Back to library</a>${intro('ORIGINAL STUDY BRIEF / MODULE 0'+r.module,r.title,'Read the core idea here, then explore the reference for more depth.')}<article class="article-reader"><img class="reader-logo" src="assets/nxgen-logo.png" alt="NxGen Varsity">${r.sections.map(s=>`<section><h2>${s.title}</h2><p>${s.body}</p></section>`).join('')}<div class="reader-source"><p>Further reading: ${r.creator}. This is an original study brief, not a reproduction of the linked article.</p><a class="button light" href="${r.url}" target="_blank" rel="noopener">Read the source ↗</a><button class="save-button" data-save="${r.id}">${state.saved.includes(r.id)?'✓ Saved':'+ Save brief'}</button></div></article>`;
 const doc=documents[r.document];if(!doc)return '<div class="empty">This guide is currently unavailable.</div>';index=Math.max(0,Math.min(index,doc.pages.length-1));const pg=doc.pages[index];return `<a class="reader-back" href="#resources">← Back to library</a><div class="reader-heading"><div><span class="eyebrow">NXGENVARSITY / LEARNING GUIDES</span><h1>${r.title}</h1></div><a class="button light" href="${r.url}" download>Download PDF ↓</a></div><div class="reader-toolbar"><div role="group" aria-label="Reader view"><button class="filter ${readerMode==='text'?'active':''}" data-reader-mode="text">Read online</button><button class="filter ${readerMode==='pdf'?'active':''}" data-reader-mode="pdf">PDF preview</button></div><div class="reader-font" ${readerMode==='pdf'?'hidden':''}><button data-font="-1" aria-label="Decrease reader font size">A−</button><button data-font="1" aria-label="Increase reader font size">A+</button></div><button class="save-button" data-save="${r.id}">${state.saved.includes(r.id)?'✓ Saved':'+ Save guide'}</button></div>${readerMode==='pdf'?`<div class="pdf-page-controls"><label for="reader-page">PDF page</label><select id="reader-page" data-doc="${r.id}">${doc.pages.map((pg,i)=>`<option value="${i}" ${i===index?'selected':''}>${i+1}. ${esc(pg.title)}</option>`).join('')}</select></div><div class="pdf-preview"><img src="resources/previews/${r.document}-${String(index+1).padStart(doc.pages.length>=10?2:1,'0')}.jpg" alt="Page ${index+1}: ${esc(pg.title)}. Choose Read online for accessible text."></div><p class="source-note">A rendered page from the NxGenVarsity PDF. Choose Read online for selectable text and adjustable type size.</p><div class="reader-pagination"><button class="button light" data-reader-page="${index-1}" data-doc="${r.id}" ${index===0?'disabled':''}>← Previous page</button><span>Page ${index+1} of ${doc.pages.length}</span><button class="button" data-reader-page="${index+1}" data-doc="${r.id}" ${index===doc.pages.length-1?'disabled':''}>Next page →</button></div>`:`<div class="reader-layout"><aside class="reader-toc"><label for="reader-page">Jump to a page</label><select id="reader-page" data-doc="${r.id}">${doc.pages.map((pg,i)=>`<option value="${i}" ${i===index?'selected':''}>${i+1}. ${esc(pg.title)}</option>`).join('')}</select><nav aria-label="Guide pages">${doc.pages.map((pg,i)=>`<a href="#reader/${r.id}/${i}" ${i===index?'aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span>${esc(pg.title)}</a>`).join('')}</nav></aside><article class="reading-page" style="--reader-scale:${readerScale}"><img class="reader-logo" src="assets/nxgen-logo.png" alt="NxGen Varsity"><span class="eyebrow">${esc(pg.eyebrow||doc.title)}</span><h2>${esc(pg.title)}</h2>${pg.blocks.map(readerBlock).join('')}<div class="reader-page-footer"><span>NxGenVarsity · Data Engineering & MLOps</span><span>${index+1} / ${doc.pages.length}</span></div></article></div><div class="reader-pagination"><button class="button light" data-reader-page="${index-1}" data-doc="${r.id}" ${index===0?'disabled':''}>← Previous page</button><span>Page ${index+1} of ${doc.pages.length}</span><button class="button" data-reader-page="${index+1}" data-doc="${r.id}" ${index===doc.pages.length-1?'disabled':''}>Next page →</button></div>`}`}
function drawQuestion(){const r=quizRun,q=r.qs[r.index];openModal(`<div class="modal-eyebrow">${r.title} / QUESTION ${r.index+1} OF ${r.qs.length}</div><h2 class="modal-title" id="modal-title">Build your understanding.</h2><div class="progress-track"><div class="progress-fill" style="width:${r.index/r.qs.length*100}%"></div></div><p class="quiz-question">${q.question}</p><div role="group" aria-label="Answer choices">${q.choices.map((o,i)=>`<button class="option" data-option="${i}" aria-pressed="false">${String.fromCharCode(65+i)}. ${o.text}</button>`).join('')}</div><div id="quiz-feedback" class="feedback" role="status"></div><div class="modal-actions"><button class="button" id="submit-answer" disabled>Check answer →</button><button class="button" id="next-question" hidden>${r.index===r.qs.length-1?'See my result':'Next question'} →</button></div><p class="source-note">Choose once, read the explanation, then continue. You can start a new attempt after reviewing your result.</p>`)}
function submitAnswer(){const r=quizRun;if(!r||r.checked||r.selected===null)return;r.checked=true;const q=r.qs[r.index],correct=q.choices[r.selected].correct;r.responses.push({correct,selected:r.selected});$$('[data-option]').forEach((b,i)=>{b.disabled=true;if(q.choices[i].correct)b.classList.add('correct-answer');else if(i===r.selected)b.classList.add('wrong-answer')});const f=$('#quiz-feedback');f.className=`feedback ${correct?'success':'error'}`;f.textContent=(correct?'That’s right. ':'Keep this connection in mind. ')+q.explanation;$('#submit-answer').hidden=true;$('#next-question').hidden=false}
function quizResult(){const r=quizRun;const score=Math.round(r.responses.filter(a=>a.correct).length/r.qs.length*100);if(!r.finished){let prior=state.quizzes[r.key];state.quizzes[r.key]={version:2,best:Math.max(score,typeof prior==='object'?prior.best||0:0),last:score,attempts:(typeof prior==='object'?prior.attempts||0:0)+1};r.finished=true;save();render()}openModal(`<div class="modal-eyebrow">${r.title} / YOUR RESULT</div><h2 class="modal-title" id="modal-title">${score>=80?'The ideas are connecting.':'A good place to keep learning.'}</h2><div class="quiz-score">${score}% <span>${r.responses.filter(a=>a.correct).length} of ${r.qs.length} correct · ${score>=80?'Passed':'Pass mark: 80%'}</span></div><p class="quiz-progress">Best result: ${state.quizzes[r.key].best}% · Attempt ${state.quizzes[r.key].attempts}</p><div class="modal-actions"><button class="button" data-quiz="${r.key}">Try a fresh attempt →</button><button class="button light" data-resource="quizbook">Read the revision workbook</button></div><h3 class="review-heading">Review your answers</h3>${r.qs.map((q,i)=>`<article class="quiz-review"><b>${i+1}. ${q.question}</b><p class="${r.responses[i].correct?'correct-label':'wrong-label'}">${r.responses[i].correct?'✓ Correct':'↻ Review'} · Your answer: ${esc(q.choices[r.responses[i].selected].text)}</p>${r.responses[i].correct?'':`<p>Correct answer: ${esc(q.choices.find(c=>c.correct).text)}</p>`}<p>${q.explanation}</p></article>`).join('')}`)}
function toggleSaved(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();if(page==='resources')$('#resource-grid').innerHTML=resourceCards();else $$('[data-save]').filter(b=>b.dataset.save===id).forEach(b=>{b.textContent=state.saved.includes(id)?'✓ Saved':'+ Save';b.setAttribute('aria-pressed',state.saved.includes(id)?'true':'false')});toast(state.saved.includes(id)?'Resource saved.':'Resource removed from saved.')}
function exportNotes(){const content=allLessons().filter(l=>state.notes[l.id]?.trim()).map(l=>`${l.title}\n${state.notes[l.id]}`).join('\n\n');if(!content){toast('Add a lesson note to start your export.');return}const url=URL.createObjectURL(new Blob(['NXGENVARSITY · DATA STUDIO NOTEBOOK\n\n'+content],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='data-studio-notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{
 const t=e.target.closest('button,a');if(!t)return;
 if(t.classList.contains('skip')){e.preventDefault();$('#main').focus();return}
 if(t.dataset.resource){if($('#modal').open)$('#modal').close();resourceRoute(t.dataset.resource);return}
 if(t.dataset.lesson){lesson(t.dataset.lesson);return}
 if(t.dataset.route){location.hash=t.dataset.route;return}
 if(t.dataset.quiz){quiz(t.dataset.quiz);return}
 if(t.dataset.note){state.notes[t.dataset.note]=$('#lesson-note').value;save();toast('Note saved to your notebook.');return}
 if(t.dataset.complete){const id=t.dataset.complete;state.notes[id]=$('#lesson-note').value;state.completed=state.completed.includes(id)?state.completed.filter(x=>x!==id):[...state.completed,id];save();render();lesson(id);toast(state.completed.includes(id)?'Lesson completed. Keep connecting the ideas.':'Lesson marked incomplete.');return}
 if(t.dataset.save){toggleSaved(t.dataset.save);return}
 if(t.dataset.filter){resourceFilter=t.dataset.filter;$$('[data-filter]').forEach(b=>b.classList.toggle('active',b===t));$('#resource-grid').innerHTML=resourceCards();return}
 if(t.dataset.videoFilter){videoFilter=t.dataset.videoFilter;$$('[data-video-filter]').forEach(b=>b.classList.toggle('active',b===t));$('#video-grid').innerHTML=videoCards();return}
 if(t.dataset.play){const r=resources.find(r=>r.id===t.dataset.play);$('#video-player').innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${r.video}?rel=0" title="${esc(r.title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`;return}
 if(t.dataset.readerMode){readerMode=t.dataset.readerMode;render();return}
 if(t.dataset.readerPage!==undefined){location.hash=`reader/${t.dataset.doc}/${t.dataset.readerPage}`;return}
 if(t.dataset.font){readerScale=Math.max(.9,Math.min(1.35,readerScale+Number(t.dataset.font)*.1));$('.reading-page')?.style.setProperty('--reader-scale',readerScale);return}
 if(t.dataset.move!==undefined){const i=Number(t.dataset.move),j=i+Number(t.dataset.direction);if(j<0||j>=pipeline.length)return;[pipeline[i],pipeline[j]]=[pipeline[j],pipeline[i]];$('#pipeline-steps').innerHTML=pipelineMarkup();$('#lab-feedback').textContent='';return}
 if(t.id==='check-pipeline'){const ok=pipeline.every((s,i)=>s===pipelineCorrect[i]),f=$('#lab-feedback');f.className=`feedback ${ok?'success':'error'}`;f.textContent=ok?'Well connected. Validate inputs, prepare features, train and evaluate before release. Monitoring feeds back into earlier stages.':'Start with ingestion and data validation. Features must be ready before training, and evaluation must come before release.';if(ok){state.lab=true;save()}return}
 if(t.id==='reset-pipeline'){pipeline=['Deploy & monitor','Validate data','Train model','Ingest data','Evaluate model','Engineer features'];$('#pipeline-steps').innerHTML=pipelineMarkup();$('#lab-feedback').textContent='';return}
 if(t.id==='profile-button'){login();return}if(t.id==='use-demo'){signIn();return}
 if(t.id==='logout'){session=false;try{sessionStorage.removeItem('data-studio-demo')}catch{}$('#modal').close();render();toast('Signed out. Your browser learning record is saved.');return}
 if(t.id==='profile-progress'||t.classList.contains('modal-close')){$('#modal').close();return}
 if(t.dataset.option!==undefined){if(!quizRun||quizRun.checked)return;quizRun.selected=Number(t.dataset.option);$$('[data-option]').forEach(o=>{o.classList.toggle('selected',o===t);o.setAttribute('aria-pressed',o===t?'true':'false')});$('#submit-answer').disabled=false;return}
 if(t.id==='submit-answer'){submitAnswer();return}
 if(t.id==='next-question'){if(!quizRun?.checked)return;if(quizRun.index===quizRun.qs.length-1)quizResult();else{quizRun.index++;quizRun.selected=null;quizRun.checked=false;drawQuestion()}return}
 if(t.id==='export-notes')exportNotes();
});
document.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();if($('#email').value.trim().toLowerCase()==='student@datastudio.demo'&&$('#password').value==='LearnData123!')signIn();else $('#login-error').textContent='Use the demo email and password shown below, or choose “Use demo account”.'}});
document.addEventListener('input',e=>{
 if(e.target.id==='lesson-search'){const q=e.target.value.trim().toLowerCase();let count=0;$$('[data-module]').forEach(row=>{const m=modules.find(x=>x.id===Number(row.dataset.module));const match=(`${m.name} ${m.description} ${m.lessons.map(l=>l.title+' '+l.objective+' '+l.sections.map(s=>s.body).join(' ')).join(' ')}`).toLowerCase().includes(q);row.hidden=!match;row.open=!!q&&match;if(match)count++});$('#search-empty').hidden=count>0}
 if(e.target.id==='resource-search'){resourceSearch=e.target.value.toLowerCase();$('#resource-grid').innerHTML=resourceCards()}
 if(e.target.id==='lesson-note'){state.notes[e.target.dataset.lesson]=e.target.value;save()}
});
document.addEventListener('change',e=>{if(e.target.id==='reader-page')location.hash=`reader/${e.target.dataset.doc}/${e.target.value}`});
window.addEventListener('hashchange',()=>{if($('#modal').open)$('#modal').close();render();window.scrollTo(0,0)});
Promise.all(['data.json','resources.json','documents.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw new Error('Learning content unavailable');return r.json()}))).then(([d,r,docs])=>{modules=d;resources=r;documents=docs;state.saved=state.saved.map(id=>id==='syllabus'?'guide':id).filter(id=>resources.some(r=>r.id===id));save();render()}).catch(()=>{$('#main').innerHTML='<div class="empty">The learning content could not load. Please refresh the page to try again.</div>'});
